def calc(expr: str) -> int | str:
    tokens: list[int | str] = []
    i = 0
    n = len(expr)
    while i < n:
        ch = expr[i]
        if ch.isspace():
            i += 1
        elif '0' <= ch <= '9':
            j = i + 1
            while j < n and '0' <= expr[j] <= '9':
                j += 1
            s = expr[i:j]
            if len(s) <= 4000:
                tokens.append(int(s))
            else:
                val = 0
                for k in range(0, len(s), 1000):
                    chunk = s[k:k + 1000]
                    val = val * (10 ** len(chunk)) + int(chunk)
                tokens.append(val)
            i = j
        else:
            tokens.append(ch)
            i += 1

    pos = 0
    m = len(tokens)

    def parse_expr() -> int:
        nonlocal pos
        val = parse_term()
        while pos < m and tokens[pos] in ('+', '-'):
            op = tokens[pos]
            pos += 1
            rhs = parse_term()
            if op == '+':
                val += rhs
            else:
                val -= rhs
        return val

    def parse_term() -> int:
        nonlocal pos
        val = parse_unary()
        while pos < m and tokens[pos] in ('*', '/', '%'):
            op = tokens[pos]
            pos += 1
            rhs = parse_unary()
            if op == '*':
                val *= rhs
            elif op == '/':
                if rhs == 0:
                    raise ZeroDivisionError
                q = abs(val) // abs(rhs)
                if (val < 0) ^ (rhs < 0):
                    q = -q
                val = q
            else:
                if rhs == 0:
                    raise ZeroDivisionError
                r = abs(val) % abs(rhs)
                if val < 0:
                    r = -r
                val = r
        return val

    def parse_unary() -> int:
        nonlocal pos
        stack: list[tuple[bool, int]] = []
        while True:
            neg = False
            while pos < m and tokens[pos] == '-':
                pos += 1
                neg = not neg
            val = parse_atom()
            if pos < m and tokens[pos] == '^':
                pos += 1
                stack.append((neg, val))
            else:
                if neg:
                    val = -val
                break
        while stack:
            neg, base = stack.pop()
            if val < 0:
                raise ValueError
            val = base ** val
            if neg:
                val = -val
        return val

    def parse_atom() -> int:
        nonlocal pos
        tok = tokens[pos]
        if tok == '(':
            pos += 1
            val = parse_expr()
            pos += 1
            return val
        pos += 1
        return tok  # type: ignore[return-value]

    try:
        return parse_expr()
    except (ZeroDivisionError, ValueError):
        return "error"
